using System.IO;
using System.Text.Json;
using System.Windows;
using System.Windows.Controls;
using CDG.AuditPilot.Application;
using CDG.AuditPilot.Infrastructure;
using CDG.AuditPilot.Reporting;
using Microsoft.Win32;
namespace CDG.AuditPilot.Desktop;
public partial class MainWindow {
 private readonly System.Windows.Threading.DispatcherTimer backupTimer=new(){Interval=TimeSpan.FromMinutes(5)};
 private void AutomaticBackup(){try{var password=SecretStore.Load("backup-key");if(password.Length==0){password=Convert.ToBase64String(System.Security.Cryptography.RandomNumberGenerator.GetBytes(32));SecretStore.Save("backup-key",password);}var folder=App.DataDirectory+"-AutoBackups";Directory.CreateDirectory(folder);BackupService.Create(App.DataDirectory,Path.Combine(folder,DateTime.UtcNow.ToString("yyyyMMdd-HHmmss")+".cdgbak"),password);foreach(var old in new DirectoryInfo(folder).GetFiles("*.cdgbak").OrderByDescending(x=>x.Name).Skip(10))old.Delete();}catch(Exception ex){App.WriteTechnicalError(ex);StatusText.Text="Échec de sauvegarde automatique. Faites une sauvegarde manuelle.";}}
 private void InitializeModules(){
  backupTimer.Tick+=(_,_)=>AutomaticBackup();backupTimer.Start();Closed+=(_,_)=>backupTimer.Stop();

  Tabs.SelectionChanged+=(_,e)=>{if(ReferenceEquals(e.Source,Tabs))UpdatePage();};
  shellReady=true;UpdatePage();UpdateDashboard();
 }

 private Window Dialog(string title,Panel panel,int width=720,int height=650)=>new(){Owner=this,Title=title,Width=width,Height=height,WindowStartupLocation=WindowStartupLocation.CenterOwner,Content=new ScrollViewer{Content=panel,VerticalScrollBarVisibility=ScrollBarVisibility.Auto}};
 private static TextBox Field(Panel panel,string label,string value,bool multiline=false){panel.Children.Add(new TextBlock{Text=label,Margin=new Thickness(0,8,0,2)});var t=new TextBox{Text=value,AcceptsReturn=multiline,TextWrapping=TextWrapping.Wrap,MinHeight=multiline?65:26};panel.Children.Add(t);return t;}
 private static Button Button(Panel panel,string label,Action action){var b=new Button{Content=label,Margin=new Thickness(0,8,0,0),Padding=new Thickness(8)};b.Click+=(_,_)=>{try{action();}catch(Exception ex){App.WriteTechnicalError(ex);MessageBox.Show(ex is ArgumentException or InvalidDataException or InvalidOperationException?ex.Message:"Opération impossible. Vérifiez le fichier, le mot de passe et les droits d’accès.");}};panel.Children.Add(b);return b;}
 private void EvidenceDialog(){if(!RequireMission())return;var panel=new StackPanel{Margin=new Thickness(15)};var list=new ListBox{Height=280,DisplayMemberPath="OriginalFileName"};panel.Children.Add(list);void RefreshEvidence()=>list.ItemsSource=data.Evidence.Where(x=>x.MissionId==mission!.Id).ToList();RefreshEvidence();var origin=Field(panel,"Origine / interlocuteur / date de réception","");
  Button(panel,"Importer une preuve (copie locale)",()=>{var d=new OpenFileDialog();if(d.ShowDialog(this)!=true)return;var evidence=new EvidenceStore(App.DataDirectory).Import(mission!.Id,d.FileName,origin.Text);data.Evidence.Add(evidence);Save();RefreshEvidence();});
  Button(panel,"Vérifier SHA-256",()=>{if(list.SelectedItem is Evidence e)MessageBox.Show(new EvidenceStore(App.DataDirectory).Verify(e)?"Empreinte conforme.":"Attention : preuve altérée.");});
  Button(panel,"Exporter une copie vérifiée",()=>{if(list.SelectedItem is not Evidence e)return;var d=new SaveFileDialog{FileName=e.OriginalFileName};if(d.ShowDialog(this)==true)new EvidenceStore(App.DataDirectory).Export(e,d.FileName);});
  Dialog("Preuves de la mission",panel).ShowDialog();
 }
 private void EditFinding(){if(FindingsGrid.SelectedItem is not Finding selected){MessageBox.Show("Sélectionnez un constat dans l’onglet Constats et risques.");return;}var panel=new StackPanel{Margin=new Thickness(15)};var description=Field(panel,"Situation observée",selected.Description,true);var criterion=Field(panel,"Critère attendu",selected.Criterion);var cause=Field(panel,"Cause présumée",selected.Cause);var consequence=Field(panel,"Conséquence",selected.Consequence);var evidence=Field(panel,"Référence ou mention preuve absente",selected.Evidence);var impact=Field(panel,"Impact 1–5",selected.Impact.ToString());var likelihood=Field(panel,"Probabilité 1–5",selected.Likelihood.ToString());var proofs=new ListBox{Height=110,SelectionMode=SelectionMode.Multiple,DisplayMemberPath="OriginalFileName",ItemsSource=data.Evidence.Where(x=>x.MissionId==selected.MissionId).ToList()};panel.Children.Add(proofs);foreach(var e in data.Evidence.Where(x=>selected.EvidenceIds.Contains(x.Id)))proofs.SelectedItems.Add(e);var validated=new CheckBox{Content="Je valide humainement le constat et la cotation",IsChecked=selected.Validated,Margin=new Thickness(0,10,0,0)};panel.Children.Add(validated);var window=Dialog("Revue du constat",panel);
  Button(panel,"Enregistrer",()=>{if(!int.TryParse(impact.Text,out int i)||!int.TryParse(likelihood.Text,out int l)||i is <1 or >5||l is <1 or >5)throw new ArgumentException("Cotation de 1 à 5 attendue.");if(string.IsNullOrWhiteSpace(description.Text))throw new ArgumentException("Description obligatoire.");var item=selected with{Description=description.Text,Criterion=criterion.Text,Cause=cause.Text,Consequence=consequence.Text,Evidence=evidence.Text,Impact=i,Likelihood=l,Scoring=data.RiskMethod,EvidenceIds=proofs.SelectedItems.Cast<Evidence>().Select(x=>x.Id).ToArray(),Validated=validated.IsChecked==true,Reviewer=validated.IsChecked==true?Environment.UserName:""};var index=data.Findings.IndexOf(selected);data.Findings[index]=item;try{Save();}catch{data.Findings[index]=selected;throw;}Refresh();window.Close();});window.ShowDialog();
 }
 private void EditAction(){if(ActionsGrid.SelectedItem is not AuditAction selected){MessageBox.Show("Sélectionnez une action dans le plan d’actions.");return;}var panel=new StackPanel{Margin=new Thickness(15)};var description=Field(panel,"Action recommandée",selected.Description,true);var owner=Field(panel,"Responsable",selected.Owner);var priority=Field(panel,"Priorité",selected.Priority);var date=new DatePicker{SelectedDate=selected.DueDate};panel.Children.Add(new TextBlock{Text="Échéance"});panel.Children.Add(date);var status=new ComboBox{ItemsSource=new[]{"À planifier","Planifiée","En cours","Terminée","Abandonnée"},SelectedItem=selected.Status};panel.Children.Add(status);var hours=Field(panel,"Charge estimée (heures)",selected.EstimatedHours.ToString());var cost=Field(panel,"Coût estimé (EUR)",selected.EstimatedCost.ToString());var effectiveness=Field(panel,"Contrôle d’efficacité",selected.Effectiveness,true);var dependencies=new ListBox{ItemsSource=data.Actions.Where(a=>a.MissionId==selected.MissionId&&a.Id!=selected.Id).ToArray(),DisplayMemberPath="Description",SelectionMode=SelectionMode.Multiple,Height=100};panel.Children.Add(new TextBlock{Text="Actions préalables (dépendances)"});panel.Children.Add(dependencies);foreach(var a in data.Actions.Where(a=>selected.Dependencies.Contains(a.Id)))dependencies.SelectedItems.Add(a);var w=Dialog("Action et suivi",panel);
  Button(panel,"Enregistrer",()=>{if(string.IsNullOrWhiteSpace(description.Text)||!decimal.TryParse(hours.Text,out var h)||h<0||!decimal.TryParse(cost.Text,out var c)||c<0)throw new ArgumentException("Description, charge et coût valides obligatoires.");data.Actions[data.Actions.IndexOf(selected)]=selected with{Description=description.Text,Owner=owner.Text,Priority=priority.Text,DueDate=date.SelectedDate,Status=status.SelectedItem as string??"À planifier",EstimatedHours=h,EstimatedCost=c,Effectiveness=effectiveness.Text,Dependencies=dependencies.SelectedItems.Cast<AuditAction>().Select(a=>a.Id).ToArray()};try{Save();}catch{data.Actions[data.Actions.FindIndex(a=>a.Id==selected.Id)]=selected;throw;}Refresh();w.Close();});w.ShowDialog();
 }
 private void Search(){var panel=new StackPanel{Margin=new Thickness(15)};var query=Field(panel,"Recherche clients, missions, constats, actions","");var results=new ListBox{Height=380};panel.Children.Add(results);var w=Dialog("Recherche",panel);query.TextChanged+=(_,_)=>{var term=query.Text;results.ItemsSource=data.Clients.Where(x=>x.Name.Contains(term,StringComparison.CurrentCultureIgnoreCase)).Select(x=>"Client : "+x.Name).Concat(data.Missions.Where(x=>(x.Title+" "+x.Reference).Contains(term,StringComparison.CurrentCultureIgnoreCase)).Select(x=>"Mission : "+x.Reference+" — "+x.Title)).Concat(data.Findings.Where(x=>x.Description.Contains(term,StringComparison.CurrentCultureIgnoreCase)).Select(x=>"Constat : "+data.Missions.Single(m=>m.Id==x.MissionId).Title+" — "+x.Description)).Concat(data.Actions.Where(x=>x.Description.Contains(term,StringComparison.CurrentCultureIgnoreCase)).Select(x=>"Action : "+x.Description)).Take(500).ToArray();};w.ShowDialog();}
 private void Journal(){var panel=new StackPanel{Margin=new Thickness(15)};using var db=new Microsoft.Data.Sqlite.SqliteConnection(new Microsoft.Data.Sqlite.SqliteConnectionStringBuilder{DataSource=Path.Combine(App.DataDirectory,"auditpilot.db"),Mode=Microsoft.Data.Sqlite.SqliteOpenMode.ReadOnly}.ToString());db.Open();using var cmd=db.CreateCommand();cmd.CommandText="SELECT Id,SavedUtc,Actor FROM WorkspaceRevisions ORDER BY Id DESC LIMIT 500";using var reader=cmd.ExecuteReader();var rows=new List<string>();while(reader.Read())rows.Add($"Révision {reader.GetInt64(0)} — {reader.GetString(1)} — {reader.GetString(2)}");panel.Children.Add(new ListBox{ItemsSource=rows,Height=450});Dialog("Historique de sauvegarde — instantanés conservés en base",panel).ShowDialog();}
 private void ExportMission(){if(!RequireMission())return;var d=new SaveFileDialog{Filter="Mission chiffrée|*.cdgbak",FileName="Mission-"+mission!.Id.ToString("N")+".cdgbak"};if(d.ShowDialog(this)!=true)return;var password=BackupPassword("Exporter une mission complète");if(password is null)return;var stage=Path.Combine(Path.GetTempPath(),"cdg-mission-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(stage);try{var db=Path.Combine(stage,"auditpilot.db");new AuditWorkspace(db).InitializeAsync().GetAwaiter().GetResult();var subset=new AuditData{Clients=data.Clients.Where(x=>x.Id==mission.ClientId).ToList(),Missions=[mission],Contacts=data.Contacts.Where(x=>x.ClientId==mission.ClientId).ToList(),Sites=data.Sites.Where(x=>x.ClientId==mission.ClientId).ToList(),Interviews=data.Interviews.Where(x=>x.MissionId==mission.Id).ToList(),Findings=data.Findings.Where(x=>x.MissionId==mission.Id).ToList(),Actions=data.Actions.Where(x=>x.MissionId==mission.Id).ToList(),Evidence=data.Evidence.Where(x=>x.MissionId==mission.Id).ToList(),RiskMethod=data.RiskMethod};new CaseworkStore(db).Save(subset);var sessions=new QuestionnaireStore(Path.Combine(App.DataDirectory,"auditpilot.db")).ListAsync(mission.Id).GetAwaiter().GetResult();foreach(var session in sessions)new QuestionnaireStore(db).SaveAsync(session).GetAwaiter().GetResult();var source=Path.Combine(App.DataDirectory,"Missions",mission.Id.ToString("N"));if(Directory.Exists(source))foreach(var file in Directory.GetFiles(source,"*",SearchOption.AllDirectories)){var dest=Path.Combine(stage,Path.GetRelativePath(App.DataDirectory,file));Directory.CreateDirectory(Path.GetDirectoryName(dest)!);File.Copy(file,dest);}BackupService.Create(stage,d.FileName,password);StatusText.Text="Mission exportée. Une restauration de cet export remplace le dossier ouvert et conserve son ancienne copie.";}finally{Microsoft.Data.Sqlite.SqliteConnection.ClearAllPools();Directory.Delete(stage,true);}}
 private void EditRiskMethod(){var panel=new StackPanel{Margin=new Thickness(15)};var review=Field(panel,"Seuil de surveillance (1–24)",data.RiskMethod.ReviewThreshold.ToString());var high=Field(panel,"Seuil élevé (2–25)",data.RiskMethod.HighThreshold.ToString());panel.Children.Add(new TextBlock{Text="Les évaluations existantes gardent leur méthode. Réviser un constat applique la nouvelle méthode.",TextWrapping=TextWrapping.Wrap});var w=Dialog("Méthode de cotation",panel,600,330);Button(panel,"Enregistrer une version",()=>{if(!int.TryParse(review.Text,out int r)||!int.TryParse(high.Text,out int h)||r<1||h<=r||h>25)throw new ArgumentException("Seuils : 1 ≤ surveillance < élevé ≤ 25.");data.RiskMethod=new(r,h,data.RiskMethod.Version+1);Save();w.Close();});w.ShowDialog();}
 private void EditClient(){if(client is null){MessageBox.Show("Sélectionnez un client.");return;}var panel=new StackPanel{Margin=new Thickness(15)};var name=Field(panel,"Raison sociale",client.Name);var email=Field(panel,"Courriel du client",client.Email);var contactName=Field(panel,"Nouveau contact : nom","");var function=Field(panel,"Fonction","");var contactEmail=Field(panel,"Courriel du contact","");var phone=Field(panel,"Téléphone","");var site=Field(panel,"Nouvel établissement : nom","");var address=Field(panel,"Adresse","");var list=new ListBox{Height=110,ItemsSource=data.Contacts.Where(c=>c.ClientId==client.Id).Select(c=>c.Name+" — "+c.Function).Concat(data.Sites.Where(c=>c.ClientId==client.Id).Select(c=>c.Name+" — "+c.Address)).ToArray()};panel.Children.Add(list);var w=Dialog("Client, contacts et établissements",panel);Button(panel,"Enregistrer",()=>{if(string.IsNullOrWhiteSpace(name.Text))throw new ArgumentException("Raison sociale obligatoire.");client.Name=name.Text;client.Email=email.Text;if(!string.IsNullOrWhiteSpace(contactName.Text))data.Contacts.Add(new(Guid.NewGuid(),client.Id,contactName.Text,function.Text,contactEmail.Text,phone.Text));if(!string.IsNullOrWhiteSpace(site.Text))data.Sites.Add(new(Guid.NewGuid(),client.Id,site.Text,address.Text));Save();Refresh();w.Close();});w.ShowDialog();}
 private void EditMission(){if(!RequireMission())return;var panel=new StackPanel{Margin=new Thickness(15)};var title=Field(panel,"Intitulé",mission!.Title);var reference=Field(panel,"Référence unique",mission.Reference);var scope=Field(panel,"Périmètre de la mission",mission.Scope,true);var status=new ComboBox{ItemsSource=Enum.GetValues<CDG.AuditPilot.Domain.MissionStatus>(),SelectedItem=mission.Status};panel.Children.Add(status);var w=Dialog("Mission",panel);Button(panel,"Enregistrer",()=>{if(string.IsNullOrWhiteSpace(title.Text)||string.IsNullOrWhiteSpace(reference.Text)||data.Missions.Any(x=>x.Id!=mission.Id&&x.Reference==reference.Text))throw new ArgumentException("Titre et référence unique obligatoires.");mission.Title=title.Text;mission.Reference=reference.Text;mission.Scope=scope.Text;mission.Status=(CDG.AuditPilot.Domain.MissionStatus)status.SelectedItem;Save();Refresh();w.Close();});w.ShowDialog();}
 private ReportBrand Brand(){var path=Path.Combine(App.DataDirectory,"report-brand.json");return File.Exists(path)?JsonSerializer.Deserialize<ReportBrand>(File.ReadAllText(path))??new():new();}
 private void SettingsDialog(){var panel=new StackPanel{Margin=new Thickness(15)};panel.Children.Add(new TextBlock{Text="Clé API chiffrée par Windows pour ce compte utilisateur."});var key=new PasswordBox{Password=SecretStore.Load("secrets")};panel.Children.Add(key);var brand=Brand();var org=Field(panel,"Organisation",brand.Organization);var title=Field(panel,"Titre du rapport",brand.Title);var footer=Field(panel,"Mention de confidentialité",brand.Footer);var w=Dialog("Paramètres",panel,650,430);Button(panel,"Enregistrer",()=>{SecretStore.Save("secrets",key.Password);File.WriteAllText(Path.Combine(App.DataDirectory,"report-brand.json"),JsonSerializer.Serialize(new ReportBrand(org.Text,title.Text,footer.Text)));w.Close();});w.ShowDialog();key.Clear();}
 private void ExportDocuments(){if(!RequireMission())return;var d=new SaveFileDialog{Filter="Word modifiable|*.docx|PDF|*.pdf|Plan d’actions Excel|*.xlsx",FileName="Audit-"+mission!.Id.ToString("N")};if(d.ShowDialog(this)!=true)return;
  var sessions=new QuestionnaireStore(Path.Combine(App.DataDirectory,"auditpilot.db")).ListAsync(mission.Id).GetAwaiter().GetResult();var lines=ReportExporter.Content(data,mission.Id,Brand(),sessions);var folder=Path.Combine(App.DataDirectory,"Missions",mission.Id.ToString("N"),"Flows");var images=Directory.Exists(folder)?Directory.GetFiles(folder,"*.png"):[];
  var temp=d.FileName+".tmp";try{if(d.FilterIndex==1)ReportExporter.Word(temp,lines,images);else if(d.FilterIndex==2)ReportExporter.Pdf(temp,lines,images);else ReportExporter.Excel(temp,data.Actions.Where(x=>x.MissionId==mission.Id));File.Move(temp,d.FileName,true);StatusText.Text="Export terminé : "+d.FileName;}finally{if(File.Exists(temp))File.Delete(temp);}
 }
 private string? BackupPassword(string title){var panel=new StackPanel{Margin=new Thickness(16)};panel.Children.Add(new TextBlock{Text="Mot de passe (12 caractères minimum). Conservez-le : il est nécessaire pour restaurer." ,TextWrapping=TextWrapping.Wrap});var pass=new PasswordBox();panel.Children.Add(pass);var w=Dialog(title,panel,600,240);Button(panel,"Continuer",()=>{if(pass.Password.Length<12)throw new ArgumentException("12 caractères minimum.");w.DialogResult=true;});return w.ShowDialog()==true?pass.Password:null;}
 private void Backup(){var d=new SaveFileDialog{Filter="Sauvegarde chiffrée|*.cdgbak",FileName="AuditPilot-"+DateTime.Now.ToString("yyyyMMdd-HHmm")+".cdgbak"};if(d.ShowDialog(this)!=true)return;var password=BackupPassword("Sauvegarder le dossier");if(password is null)return;Save();BackupService.Create(App.DataDirectory,d.FileName,password);StatusText.Text="Sauvegarde chiffrée créée.";}
 private void RestoreAuto(){var d=new OpenFileDialog{Filter="Sauvegarde automatique|*.cdgbak",InitialDirectory=App.DataDirectory+"-AutoBackups"};if(d.ShowDialog(this)!=true)return;var password=SecretStore.Load("backup-key");if(string.IsNullOrEmpty(password))throw new InvalidOperationException("Clé de sauvegarde automatique indisponible. Utilisez une sauvegarde manuelle.");if(MessageBox.Show(this,"Restaurer et fermer l’application ? Le dossier courant sera conservé.","Restauration",MessageBoxButton.YesNo)!=MessageBoxResult.Yes)return;backupTimer.Stop();BackupService.Restore(d.FileName,App.DataDirectory,password);SecretStore.Save("backup-key",password);System.Windows.Application.Current.Shutdown();}
 private void Restore(){var d=new OpenFileDialog{Filter="Sauvegarde chiffrée|*.cdgbak"};if(d.ShowDialog(this)!=true)return;var password=BackupPassword("Restaurer le dossier");if(password is null)return;if(MessageBox.Show(this,"Restaurer cette sauvegarde ? Le dossier actuel sera conservé à côté et l’application se fermera.","Restauration",MessageBoxButton.YesNo)!=MessageBoxResult.Yes)return;BackupService.Restore(d.FileName,App.DataDirectory,password);System.Windows.Application.Current.Shutdown();}
}
